62	// Reserve 0 as default.
63	let _highlightNextDigit = 1;
64	
65	const _highlightKeyMap: Dictionary<number> = {};
66	
67	const getSavedStates = makeInner<{
68	    normalFill: ZRColor
69	    normalStroke: ZRColor
70	    selectFill?: ZRColor
71	    selectStroke?: ZRColor
72	}, Path>();
73	
74	const getComponentStates = makeInner<{
75	    isBlured: boolean
76	}, SeriesModel | ComponentModel>();
77	
78	export const HOVER_STATE_NORMAL: 0 = 0;
79	export const HOVER_STATE_BLUR: 1 = 1;
80	export const HOVER_STATE_EMPHASIS: 2 = 2;
81	
82	export const SPECIAL_STATES = ['emphasis', 'blur', 'select'] as const;
83	export const DISPLAY_STATES = ['normal', 'emphasis', 'blur', 'select'] as const;
84	
85	export const Z2_EMPHASIS_LIFT = 10;
86	export const Z2_SELECT_LIFT = 9;
87	
88	export const HIGHLIGHT_ACTION_TYPE = 'highlight';
89	export const DOWNPLAY_ACTION_TYPE = 'downplay';
90	
91	export const SELECT_ACTION_TYPE = 'select';
92	export const UNSELECT_ACTION_TYPE = 'unselect';
93	export const TOGGLE_SELECT_ACTION_TYPE = 'toggleSelect';
94	
95	type ExtendedProps = {
96	    __highByOuter: number
97	
98	    __highDownSilentOnTouch: boolean
99	
100	    __highDownDispatcher: boolean
101	};
102	type ExtendedElement = Element & ExtendedProps;
103	type ExtendedDisplayable = Displayable & ExtendedProps;
104	
105	function hasFillOrStroke(fillOrStroke: string | PatternObject | GradientObject) {
106	    return fillOrStroke != null && fillOrStroke !== 'none';
107	}
108	
109	function doChangeHoverState(el: ECElement, stateName: DisplayState, hoverStateEnum: 0 | 1 | 2) {
110	    if (el.onHoverStateChange && (el.hoverState || 0) !== hoverStateEnum) {
111	        el.onHoverStateChange(stateName);
112	    }
113	    el.hoverState = hoverStateEnum;
114	}
115	
116	function singleEnterEmphasis(el: ECElement) {
117	    // Only mark the flag.
118	    // States will be applied in the echarts.ts in next frame.
119	    doChangeHoverState(el, 'emphasis', HOVER_STATE_EMPHASIS);
120	}
121	
122	function singleLeaveEmphasis(el: ECElement) {
123	    // Only mark the flag.
124	    // States will be applied in the echarts.ts in next frame.
125	    if (el.hoverState === HOVER_STATE_EMPHASIS) {
126	        doChangeHoverState(el, 'normal', HOVER_STATE_NORMAL);
127	    }
128	}
129	
130	function singleEnterBlur(el: ECElement) {
131	    doChangeHoverState(el, 'blur', HOVER_STATE_BLUR);
132	}
133	
134	function singleLeaveBlur(el: ECElement) {
135	    if (el.hoverState === HOVER_STATE_BLUR) {
136	        doChangeHoverState(el, 'normal', HOVER_STATE_NORMAL);
137	    }
138	}
139	
140	function singleEnterSelect(el: ECElement) {
141	    el.selected = true;
142	}
143	function singleLeaveSelect(el: ECElement) {
144	    el.selected = false;
145	}
146	
147	function updateElementState<T>(
148	    el: ExtendedElement,
149	    updater: (this: void, el: Element, commonParam?: T) => void,
150	    commonParam?: T
151	) {
152	    updater(el, commonParam);
153	}
154	
155	function traverseUpdateState<T>(
156	    el: ExtendedElement,
157	    updater: (this: void, el: Element, commonParam?: T) => void,
158	    commonParam?: T
159	) {
160	    updateElementState(el, updater, commonParam);
161	    el.isGroup && el.traverse(function (child: ExtendedElement) {
162	        updateElementState(child, updater, commonParam);
163	    });
164	}
165	
166	export function setStatesFlag(el: ECElement, stateName: DisplayState) {
167	    switch (stateName) {
168	        case 'emphasis':
169	            el.hoverState = HOVER_STATE_EMPHASIS;
170	            break;
171	        case 'normal':
172	            el.hoverState = HOVER_STATE_NORMAL;
173	            break;
174	        case 'blur':
175	            el.hoverState = HOVER_STATE_BLUR;
176	            break;
177	        case 'select':
178	            el.selected = true;
179	    }
180	}
181	
182	/**
183	 * If we reuse elements when rerender.
184	 * DON'T forget to clearStates before we update the style and shape.
185	 * Or we may update on the wrong state instead of normal state.
186	 */
187	export function clearStates(el: Element) {
188	    if (el.isGroup) {
189	        el.traverse(function (child) {
190	            child.clearStates();
191	        });
192	    }
193	    else {
194	        el.clearStates();
195	    }
196	}
197	
198	function getFromStateStyle(
199	    el: Displayable,
200	    props: (keyof PathStyleProps)[],
201	    toStateName: string,
202	    defaultValue?: PathStyleProps
203	): PathStyleProps {
204	    const style = el.style;
205	    const fromState: PathStyleProps = {};
206	    for (let i = 0; i < props.length; i++) {
207	        const propName = props[i];
208	        const val = style[propName];
209	        (fromState as any)[propName] = val == null ? (defaultValue && defaultValue[propName]) : val;
210	    }
211	    for (let i = 0; i < el.animators.length; i++) {
212	        const animator = el.animators[i];
213	        if (animator.__fromStateTransition
214	            // Don't consider the animation to emphasis state.
215	            && animator.__fromStateTransition.indexOf(toStateName) < 0
216	            && animator.targetName === 'style') {
217	            animator.saveTo(fromState, props);
218	        }
219	    }
220	    return fromState;
221	}
222	
223	function createEmphasisDefaultState(
224	    el: Displayable,
225	    stateName: 'emphasis',
226	    targetStates: string[],
227	    state: Displayable['states'][number]
228	): DisplayableState {
229	    const hasSelect = targetStates && indexOf(targetStates, 'select') >= 0;
230	    let cloned = false;
231	    if (el instanceof Path) {
232	        const store = getSavedStates(el);
233	        const fromFill = hasSelect ? (store.selectFill || store.normalFill) : store.normalFill;
234	        const fromStroke = hasSelect ? (store.selectStroke || store.normalStroke) : store.normalStroke;
235	        if (hasFillOrStroke(fromFill) || hasFillOrStroke(fromStroke)) {
236	            state = state || {};
237	            let emphasisStyle = state.style || {};
238	
239	            // inherit case
240	            if (emphasisStyle.fill === 'inherit') {
241	                cloned = true;
242	                state = extend({}, state);
243	                emphasisStyle = extend({}, emphasisStyle);
244	                emphasisStyle.fill = fromFill;
245	            }
246	            // Apply default color lift
247	            else if (!hasFillOrStroke(emphasisStyle.fill) && hasFillOrStroke(fromFill)) {
248	                cloned = true;
249	                // Not modify the original value.
250	                state = extend({}, state);
251	                emphasisStyle = extend({}, emphasisStyle);
252	                // Already being applied 'emphasis'. DON'T lift color multiple times.
253	                emphasisStyle.fill = liftColor(fromFill as ColorString);
254	            }
255	            // Not highlight stroke if fill has been highlighted.
256	            else if (!hasFillOrStroke(emphasisStyle.stroke) && hasFillOrStroke(fromStroke)) {
257	                if (!cloned) {
258	                    state = extend({}, state);
259	                    emphasisStyle = extend({}, emphasisStyle);
260	                }
261	                emphasisStyle.stroke = liftColor(fromStroke as ColorString);
262	            }
263	            state.style = emphasisStyle;
264	        }
265	    }
266	    if (state) {
267	        // TODO Share with textContent?
268	        if (state.z2 == null) {
269	            if (!cloned) {
270	                state = extend({}, state);
271	            }
272	            const z2EmphasisLift = (el as ECElement).z2EmphasisLift;
