428	export function blurSeries(
429	    targetSeriesIndex: number,
430	    focus: InnerFocus,
431	    blurScope: BlurScope,
432	    api: ExtensionAPI
433	) {
434	    const ecModel = api.getModel();
435	    blurScope = blurScope || 'coordinateSystem';
436	
437	    function leaveBlurOfIndices(data: SeriesData, dataIndices: ArrayLike<number>) {
438	        for (let i = 0; i < dataIndices.length; i++) {
439	            const itemEl = data.getItemGraphicEl(dataIndices[i]);
440	            itemEl && leaveBlur(itemEl);
441	        }
442	    }
443	
444	    if (targetSeriesIndex == null) {
445	        return;
446	    }
447	
448	    if (!focus || focus === 'none') {
449	        return;
450	    }
451	
452	    const targetSeriesModel = ecModel.getSeriesByIndex(targetSeriesIndex);
453	    let targetCoordSys: CoordinateSystemMaster | CoordinateSystem = targetSeriesModel.coordinateSystem;
454	    if (targetCoordSys && (targetCoordSys as CoordinateSystem).master) {
455	        targetCoordSys = (targetCoordSys as CoordinateSystem).master;
456	    }
457	
458	    const blurredSeries: SeriesModel[] = [];
459	
460	    ecModel.eachSeries(function (seriesModel) {
461	
462	        const sameSeries = targetSeriesModel === seriesModel;
463	        let coordSys: CoordinateSystemMaster | CoordinateSystem = seriesModel.coordinateSystem;
464	        if (coordSys && (coordSys as CoordinateSystem).master) {
465	            coordSys = (coordSys as CoordinateSystem).master;
466	        }
467	        const sameCoordSys = coordSys && targetCoordSys
468	            ? coordSys === targetCoordSys
469	            : sameSeries;   // If there is no coordinate system. use sameSeries instead.
470	        if (!(
471	            // Not blur other series if blurScope series
472	            blurScope === 'series' && !sameSeries
473	            // Not blur other coordinate system if blurScope is coordinateSystem
474	            || blurScope === 'coordinateSystem' && !sameCoordSys
475	            // Not blur self series if focus is series.
476	            || focus === 'series' && sameSeries
477	            // TODO blurScope: coordinate system
478	        )) {
479	            const view = api.getViewOfSeriesModel(seriesModel);
480	            view.group.traverse(function (child) {
481	                // For the elements that have been triggered by other components,
482	                // and are still required to be highlighted,
483	                // because the current is directly forced to blur the element,
484	                // it will cause the focus self to be unable to highlight, so skip the blur of this element.
485	                if ((child as ExtendedElement).__highByOuter && sameSeries && focus === 'self') {
486	                    return;
487	                }
488	                singleEnterBlur(child);
489	            });
490	
491	            if (isArrayLike(focus)) {
492	                leaveBlurOfIndices(seriesModel.getData(), focus as ArrayLike<number>);
493	            }
494	            else if (isObject(focus)) {
495	                const dataTypes = keys(focus);
496	                for (let d = 0; d < dataTypes.length; d++) {
497	                    leaveBlurOfIndices(seriesModel.getData(dataTypes[d] as SeriesDataType), focus[dataTypes[d]]);
498	                }
499	            }
500	
501	            blurredSeries.push(seriesModel);
502	
503	            getComponentStates(seriesModel).isBlured = true;
504	        }
505	    });
506	
507	    ecModel.eachComponent(function (componentType, componentModel) {
508	        if (componentType === 'series') {
509	            return;
510	        }
511	        const view = api.getViewOfComponentModel(componentModel);
512	        if (view && view.toggleBlurSeries) {
513	            view.toggleBlurSeries(blurredSeries, true, ecModel);
514	        }
515	    });
516	}
