import { createChart, removeChart } from '../test/ut/core/utHelper';
import { isHighDownDispatcher } from '../src/util/states';

// Safeguard for requirement `candlestick-non-normal-states`:
// candlestick items must respond to emphasis/blur/select states
// (regressed since v5.0.0, fixed upstream in e6dab04).
describe('candlestick-non-normal-states', function () {
    it('sets per-sign state styles and enables hover emphasis', function () {
        const chart = createChart();
        chart.setOption({
            xAxis: { data: ['a', 'b', 'c'] },
            yAxis: {},
            series: [{
                type: 'candlestick',
                data: [
                    [20, 34, 10, 38],   // positive
                    [40, 35, 30, 50],   // negative
                    [31, 38, 28, 44]    // positive
                ],
                emphasis: {
                    itemStyle: {
                        color: 'purple',
                        borderColor: 'cyan',
                        color0: 'blue',
                        borderColor0: 'brown'
                    }
                },
                blur: {
                    itemStyle: {
                        color: 'grey',
                        borderColor: 'pink',
                        color0: 'gray',
                        borderColor0: 'orange',
                        opacity: 1
                    }
                }
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as any;
        const data = seriesModel.getData();
        const elPos = data.getItemGraphicEl(0) as any;
        const elNeg = data.getItemGraphicEl(1) as any;

        // Hover emphasis must be enabled on each candlestick element.
        expect(isHighDownDispatcher(elPos)).toBe(true);
        expect(isHighDownDispatcher(elNeg)).toBe(true);

        // Emphasis state style should respect sign-specific color/borderColor.
        expect(elPos.states.emphasis.style.fill).toBe('purple');
        expect(elPos.states.emphasis.style.stroke).toBe('cyan');
        expect(elNeg.states.emphasis.style.fill).toBe('blue');
        expect(elNeg.states.emphasis.style.stroke).toBe('brown');

        // Blur state style should respect sign-specific color0/borderColor0 too.
        expect(elPos.states.blur.style.fill).toBe('grey');
        expect(elPos.states.blur.style.stroke).toBe('pink');
        expect(elNeg.states.blur.style.fill).toBe('gray');
        expect(elNeg.states.blur.style.stroke).toBe('orange');

        // Normal rendering should be untouched.
        expect(elPos.style.fill).toBeTruthy();
        expect(elPos.style.stroke).toBeTruthy();

        removeChart(chart);
    });
});

